function canon(s, lang) {
  const table = lang === "ko" ? CANON_KO : lang === "ja" ? CANON_JA : CANON_EN;
  let out = s;
  for (const [re, rep] of table) out = out.replace(re, rep);
  return out;
}
var HOIST_TAGS = ["\u3010\uC18C\uD658\uC2DC\u3011", "\u3010\u53EC\u559A\u6642\u3011", "\u3010On Summon\u3011"];
function hoistTag(s) {
  for (const tag2 of HOIST_TAGS) {
    const i = s.indexOf(tag2);
    const pre = s.slice(0, i);
    if (i > 0 && !pre.includes("\u3010") && !/\s·\s/.test(pre) && !/^\s*\[[^\]]+\]\s*$/.test(pre)) return tag2 + pre.trim() + " " + s.slice(i + tag2.length).trim();
  }
  return s;
}
function standardizeCardTexts(pools, keywordNames) {
  for (const pool of pools) {
    for (const id of Object.keys(pool)) {
      const c = pool[id];
      const ov = OVERRIDE[id];
      const ko0 = c.text;
      const fin = (txt, lang) => unifySeparators(stripCostPrefix(stripCastCost(canon(hoistTag(txt), lang))));
      if (c.text === "\u2014") {
        c.textJa ??= "\u2014";
        c.textEn ??= "\u2014";
      }
      const pre = (txt, lang) => stripKeywords(c, unifySeparators(txt), lang, keywordNames);
      if (c.text && c.text !== "\u2014") c.text = fin(ov?.ko ?? stdKo(c, pre(c.text, "ko")), "ko");
      if (c.textJa && c.textJa !== "\u2014") c.textJa = fin(ov?.ja ?? stdJa(c, pre(c.textJa, "ja")), "ja");
      if (c.textEn && c.textEn !== "\u2014") c.textEn = fin(c.textEn === ko0 ? c.text : ov?.en ?? stdEn(c, pre(c.textEn, "en")), "en");
    }
  }
}

